function T(str,st='p',color,al){const parts=String(str).split('**');const h=parts.map((p,i)=>i%2?`<b>${esc(p)}</b>`:esc(p)).join('');const c=color||DEFC[st];return `<p class="tx ${st}${al==='c'?' c':''}"${c?` style="color:${CV(c)}"`:''}>${h}</p>`;}
function AV(ini,col,s=40,dot){if(!ini)return `<span class="av empty" style="width:${s}px;height:${s}px;border-radius:${Math.round(s*.32)}px"></span>`;return `<span class="av" style="width:${s}px;height:${s}px;border-radius:${Math.round(s*.32)}px;background:${CV(col||'raw/c3a6ff')};font-size:${Math.round(s*.36)}px">${esc(ini)}${dot?'<i class="dot"></i>':''}</span>`;}
