function toast(title,sub,opts={}){$$('.toast').forEach(t=>t.remove());const el=document.createElement('div');el.className='toast'+(opts.to?' go':'');el.setAttribute('role','status');el.innerHTML=`<span class="ti">${IC(opts.icon||'star',18)}</span><span>${title?`<b>${esc(title)}</b>`:''}${sub?`<small>${esc(sub)}</small>`:''}</span>`;$('#scr').appendChild(el);if(opts.to)el.onclick=()=>{el.remove();go(opts.to);};const tm=setTimeout(()=>{el.classList.add('out');setTimeout(()=>el.remove(),320);},opts.ms||2600);el._tm=tm;}
