function applyTheme(){const t=ST.theme,o=t==='light'?'dark':'light';[document.documentElement,document.body,document.querySelector('.phone'),document.getElementById('scr')].forEach(el=>{if(!el)return;el.classList.remove('th-'+o);el.classList.add('th-'+t);el.setAttribute('data-sqt',t);});document.documentElement.style.colorScheme=t;}
