function confetti(){const c=document.createElement('canvas');c.className='conf';const scr=$('#scr');scr.appendChild(c);const W=c.width=393,H=c.height=852;const x=c.getContext('2d');const cols=['#FF9A3C','#B14CF3','#3DE0A6','#FFD166','#FF4FA3'];const P=Array.from({length:110},()=>({x:W/2+(Math.random()-.5)*80,y:H*.38,vx:(Math.random()-.5)*9,vy:-Math.random()*11-4,s:4+Math.random()*5,c:cols[Math.random()*5|0],r:Math.random()*6,vr:(Math.random()-.5)*.3}));let t=0;const f=()=>{x.clearRect(0,0,W,H);for(const p of P){p.vy+=.32;p.x+=p.vx;p.y+=p.vy;p.r+=p.vr;x.save();x.translate(p.x,p.y);x.rotate(p.r);x.fillStyle=p.c;x.fillRect(-p.s/2,-p.s/4,p.s,p.s/2);x.restore();}if(++t<130)requestAnimationFrame(f);else c.remove();};if(!matchMedia('(prefers-reduced-motion: reduce)').matches)f();}
function countUp(el,from,to,ms=900,fmt=v=>v){const t0=performance.now();const st=t=>{const p=Math.min(1,(t-t0)/ms);const e=1-Math.pow(1-p,3);el.textContent=fmt(Math.round(from+(to-from)*e));if(p<1)requestAnimationFrame(st);};requestAnimationFrame(st);}
