function run(m){if(typeof m==='function')return m();if(typeof m==='string'){if(m==='<')return back();return go(m);}if(Array.isArray(m)){const[to,t,sub,ic]=m;if(t)toast(t,sub,{icon:ic});if(to==='<')back();else if(to)go(to);}}

