function gxInit(){gxStop();const w=$('#w01');if(!w)return;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const boot=$('#boot');if(boot){$('#scr').appendChild(boot);ST.booted=true;w.style.setProperty('--bd','1350ms');const t0=performance.now();const bar=$('#bootbar'),pc=$('#bootpct');const step=t=>{const p=Math.min(1,(t-t0)/1150);const e=1-Math.pow(1-p,3);bar.style.width=e*100+'%';pc.textContent=Math.round(e*100)+'%';if(p<1)requestAnimationFrame(step);else setTimeout(()=>{boot.classList.add('done');setTimeout(()=>boot.remove(),500);},180);};requestAnimationFrame(step);boot.onclick=()=>boot.classList.add('done');}
 else w.style.setProperty('--bd','0ms');
 const on=$('#wOn');if(on){let n=248;gxT=setInterval(()=>{n+=Math.round(Math.random()*6-2);on.textContent=n;},1600);}
 const st=$('#stage');const ph=document.querySelector('.phone');if(st&&!reduce)ph.onpointermove=e=>{const r=st.getBoundingClientRect();const x=((e.clientX-r.left)/r.width-.5)*2,y=((e.clientY-r.top)/r.height-.5)*2;st.style.setProperty('--px',Math.max(-1,Math.min(1,x)).toFixed(3));st.style.setProperty('--py',Math.max(-1,Math.min(1,y)).toFixed(3));};
 const cv=w.querySelector('canvas');if(!cv||reduce)return;const ctx=cv.getContext('2d');const dpr=Math.min(2,devicePixelRatio||1);const W=393,H=852;cv.width=W*dpr;cv.height=H*dpr;ctx.scale(dpr,dpr);
 const cols=['#A45CFF','#FF4FA3','#FFD166','#3DE0A6','#FF9A3C'];
 const P=Array.from({length:52},()=>({x:Math.random()*W,y:Math.random()*H,s:1+Math.random()*3,v:.25+Math.random()*.7,c:cols[Math.random()*cols.length|0],k:Math.random()<.25?'+':(Math.random()<.5?'sq':'dot'),a:.3+Math.random()*.55,w:Math.random()*6.28}));
 const tick=()=>{ctx.clearRect(0,0,W,H);for(const p of P){p.y-=p.v;p.w+=.02;p.x+=Math.sin(p.w)*.3;if(p.y<-10){p.y=H+10;p.x=Math.random()*W;}ctx.globalAlpha=p.a*(p.y<H*.3?.6:1);ctx.fillStyle=p.c;ctx.strokeStyle=p.c;if(p.k==='sq')ctx.fillRect(p.x,p.y,p.s*1.6,p.s*1.6);else if(p.k==='+'){ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(p.x-p.s*1.6,p.y);ctx.lineTo(p.x+p.s*1.6,p.y);ctx.moveTo(p.x,p.y-p.s*1.6);ctx.lineTo(p.x,p.y+p.s*1.6);ctx.stroke();}else{ctx.beginPath();ctx.arc(p.x,p.y,p.s,0,6.28);ctx.fill();}}ctx.globalAlpha=1;if(document.body.contains(cv))gxRAF=requestAnimationFrame(tick);};gxRAF=requestAnimationFrame(tick);}

