function ageRoute(){const bd=$$('#scr input').find(i=>i.closest('label').textContent.includes('nascimento'));const m=(bd&&bd.value||'').match(/(\d\d)\/(\d\d)\/(\d{4})/);if(!m){toast('Confira a data de nascimento',null,{icon:'info'});return;}const b=new Date(+m[3],+m[2]-1,+m[1]);const now=new Date(2026,10,18);let a=now.getFullYear()-b.getFullYear();if(now<new Date(now.getFullYear(),b.getMonth(),b.getDate()))a--;go(a<13?'32':a<18?'31':'04');}
