const BAD=/\b(noob|burr[ao]|lixo|idiota|ruim demais|cala a boca)\b/i;
function sendMsg(){const i=$('#msgin');const t=(i.value||'').trim();if(!t)return;if(BAD.test(t)){ST.toneText=t;go('12');return;}ST.chat.push(['SA','raw/8b6cff','sak',t]);i.value='';renderChat();const last=$$('#chat .msg').pop();last&&last.classList.add('new');}
function reqDone(e,what){const card=e.target.closest('.card');if(!card)return;card.style.transition='opacity .3s,transform .3s';card.style.opacity='0';card.style.transform='translateX(30px)';setTimeout(()=>card.remove(),300);toast('Pedido '+what,what==='recusado'?'A pessoa só vê que não há vaga agora.':'Novo membro no squad!',{icon:what==='aceito'?'check':'x'});}

function buildSide(){let k=0;const NUM={};GROUPS.forEach(([g,ids])=>ids.forEach(id=>NUM[id]=String(++k).padStart(2,'0')));const m=$('#map');m.innerHTML=GROUPS.map(([g,ids])=>`<h4>${g}</h4>`+ids.map(id=>`<button data-to="${id}"><span>${NUM[id]}</span>${esc(SCR[id].n)}</button>`).join('')).join('');$$('#map button').forEach(b=>b.onclick=()=>{const id=b.dataset.to;ST.hist=[];if(SCR[id].sheet)ST.hist=[SCR[id].under];ST.cur=id;render();});}
function fit(){const ph=$('.phone');const emb=document.body.classList.contains('embed');const s=emb?Math.min(1,(innerHeight-28)/878,(innerWidth-28)/419):Math.min(1,(innerHeight-40)/870,(innerWidth-(innerWidth>900?380:24))/420);ph.style.transform=`scale(${s})`;ph.style.margin=`${(852*s-852)/2}px ${(393*s-393)/2}px`;}
window.addEventListener('resize',fit);
document.addEventListener('DOMContentLoaded',()=>{const QS=new URLSearchParams(location.search);if(QS.has('embed')){document.body.classList.add('embed');document.documentElement.classList.add('embed');}if(QS.get('theme')==='dark'||QS.get('theme')==='light')ST.theme=QS.get('theme');setTheme(ST.theme);buildSide();
 $$('[data-sqtheme]').forEach(b=>b.onclick=()=>{setTheme(b.dataset.sqtheme);render();});
 $('#restart').onclick=()=>{ST.hist=[];ST.cur='01';ST.booted=false;ST.voiceSeen=false;ST.chat=CHAT0.slice();render();};
 const h=location.hash.slice(1);if(SCR[h]){ST.cur=h;if(SCR[h].sheet)ST.hist=[SCR[h].under];}
 fit();render();});

document.getElementById('sidelogo').innerHTML=logo(34);
